-- Additive catalog extension. Existing items retain their IDs and a null brand.
CREATE TABLE "brands" (
    "brand_id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "code" varchar(30) NOT NULL UNIQUE,
    "name" varchar(120) NOT NULL,
    "description" text,
    "is_active" boolean NOT NULL DEFAULT true,
    "created_by" integer,
    "created_at" timestamp with time zone NOT NULL DEFAULT now(),
    "updated_by" integer,
    "updated_at" timestamp with time zone NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX "brands_name_uq" ON "brands" (lower("name"));
ALTER TABLE "items" ADD COLUMN "brand_id" integer REFERENCES "brands"("brand_id") ON DELETE RESTRICT;
CREATE INDEX "items_brand_idx" ON "items" ("brand_id");
